  "entries": [
    {
      "name_han": "祝由科",
      "logic_thesis": "疾病本质是精气神错位与‘病由’未明；不必先攻形质，而以祝说、符咒、存思移精变气，使神归其位则病自解。",
      "logic_chain": "1) 上古之病多因情志、邪祟、气机紊乱，非尽属形伤。2) 形伤用针药，神伤须先正‘由’——病因叙事与气场定位。3) 语言、符图、步罡是定向信息载体，可重写气机秩序。4) 移精变气使精神内守，邪无可寄。5) 故祝由是医道信息层疗法，与针石药物并行而非迷信替代。",
      "logic_practice": "1) 先看日主与心神宫（日支、时干）是否空亡、冲克、神煞扰神。2) 病象重‘由’：辨印星受克（精气不足）还是七杀无制（邪气外侵）。3) 用喜神五行方位择时行祝/符，忌在日主大耗、刑冲日硬开局。4) 符咒对应天干地支五行编码，按命局缺补选符。5) 事后复盘：神安（神煞减轻、印比得生）则气机回正。",
      "logic_compare": "较《素问·移精变气论》更偏操作科门；较正一符箓偏医疗语境而非纯斋醮。与辰州祝由、禁咒一脉，但更强调‘说病由’的因果澄清，而非仅驱鬼。"
    },
    {
      "name_han": "嵩山志",
      "logic_thesis": "嵩为中岳、土德之镇，山志以中正、枢纽、承天接地论证：得中气者寿、失中和者灾，修道与安命皆重‘居中守土’。",
      "logic_chain": "1) 五岳分方，嵩居天地之中，象坤土承载。2) 中岳祭典与洞天记载证明王权、道脉皆须‘得中’。3) 山形宫观布局效法中宫，稳则四维安。4) 高道择中岳修炼，取土德厚载、缓生不骤。5) 故志书逻辑是：地理中心→气运中和→人事长久。",
      "logic_practice": "1) 查日主是否缺土/土多壅滞，对中宫（辰戌丑未、戊己）强弱。2) 中和失衡（燥湿偏极）优先调土，再论财官。3) 大运入土库、丑未冲合时，做安宅、培中、守静类选择。4) 流年冲中宫忌妄动，宜固本培元。5) 用土为喜者可取‘居中’方位与时辰行事。",
      "logic_compare": "较《泰山志》重‘生发东岳’而嵩重‘镇中’，较华山险峻之金气，嵩更主厚载包容。山志叙事偏王朝礼制与中岳正统，命理映射是土德枢纽而非杀伐或升仙奇险。"
    },
    {
      "name_han": "华山志",
      "logic_thesis": "华山以险绝、西岳金气、仙真飞升传说立论：精进克己、断绝凡滞，乃能在极金肃杀之境炼形入神。",
      "logic_chain": "1) 西岳配金，主收敛、决断、肃清。2) 山势壁立万仞，象征修道须绝攀缘、单一志向。3) 仙传与洞府记录证明‘险境出真修’。4) 金气过刚则伤，过弱则懦，须以义制刚。5) 故华山逻辑是：地理金肃→心志刚断→形神超拔。",
      "logic_practice": "1) 看庚辛申酉与日主关系：金为用宜决断，金为忌宜柔制。2) 七杀有制、羊刃驾杀类格局，可取‘华山式’果断改运节点。3) 金旺流年适合断舍离、手术、法律、金属行业决策。4) 金弱遇冲宜避险峰式冒险，先补印比。5) 择西方、申酉时做清理、收口、立约之事。",
      "logic_compare": "与《武当山志》同主修道严整，但华山偏金之峭拔飞升，武当偏水火玄武镇魔。较嵩山之中和厚土，华山叙事更励志于绝境超脱与西岳刑杀之德。"
    },
    {
      "name_han": "武当山志",
      "logic_thesis": "武当以真武（玄武）镇北方、内炼与外御并重：水德沉静、火炼成真，山为道场则人可借玄武之力伏阴邪、成全真。",
      "logic_chain": "1) 真武为北方水神、荡魔天尊，象坎水之静与威。2) 志书宫观、帝敕、拳法证明王权与民间皆认其‘镇邪护命’。3) 修炼逻辑：静水深流→武火文火→形神俱妙。4) 山形如龟蛇玄武，地理与神格同构。5) 故论证：得玄武位势者能以静制动、以正胜邪。",
      "logic_practice": "1) 重点看亥子癸水与丙丁巳午：水火既济则真武格显。2) 阴邪类象（枭印攻身、鬼劫重重）用北玄武位与水日化解。3) 七杀攻身而无制，宜取‘镇’法：合杀、制杀，不宜硬抗。4) 大运入水火交战年，练静坐、忌躁进。5) 择壬癸亥子时做驱邪、安神、护宅类布局。",
      "logic_compare": "较青城之天师正一外法，武当更重玄武内炼与帝敕全真气场。与华山同为名山修真志，但武当叙事王权介入更深，命理上更强调水火交炼与镇北伏阴。"
    },
    {
      "name_han": "泰山志",
      "logic_thesis": "泰山为东岳、主生发与生死受命：封禅与岳帝信仰证明‘命自东生、鬼归岱宗’，地理之仁气决定国运与人命的起始权威。",
      "logic_chain": "1) 东岳配木，春生之德，万物资始。2) 帝王封禅告天，把人事成功上溯天道认可。3) 岱宗主生死簿传说，使山志成为命数裁判之象征地理。4) 木气条达则贵寿，折木则夭滞。5) 故逻辑链是：东方生门→天命认证→个人命运须顺生发之令。",
      "logic_practice": "1) 查甲乙寅卯与日主：木为用宜生发进取，木为忌宜修剪。2) 看年柱祖气、月令司权是否得东岳生发之令。3) 印比生身有力者，大运东方可求名、动迁、开业。4) 木被金重克或死绝之地，慎重大生死节点决策，先补印。5) 寅卯月/日做祈生、拜祖、启动类仪式择时。",
      "logic_compare": "较嵩山‘守中’、华山‘肃金’，泰山独主‘生与命权’。与一般洞天福地志相比，泰山志更浓政治神学色彩，命理映射是年命、祖德与东生之气，而非一派私传秘法。"
    },
    {
      "name_han": "九华山志",
      "logic_thesis": "九华以地藏愿力、九峰莲华之象立论：苦厄可度、地狱可空，山志逻辑是慈悲愿力重于一己飞升，转业消障优先于争气运之锋。",
      "logic_chain": "1) 山形如莲，九华得名，象清净出淤泥。2) 地藏道场使志书重心从仙真转向救度众生。3) 香火与感应录证明‘愿’可改业报轨迹。4) 修道者先消罪障再谈延寿。5) 故核心论证：地理清净+愿力场→业消则命机松动。",
      "logic_practice": "1) 先查凶煞、刑害、空亡、官鬼交战是否象‘罪障压身’。2) 印枭、正官过重或日时受冲，优先做消业、还愿、布施类时间选择。3) 忌神发动年不宜硬开财官，宜做减法与忏悔仪式对应。4) 用神得水木清气者，可借九华式清净方位静修。5) 流年合解刑冲后，再启动事业大运。",
      "logic_compare": "较青城、茅山等纯道派山志，九华更佛道交融、重愿力救度。较泰山主生死权威，九华主慈悲赦罪；命理应用更偏化解业障节点，而非封禅式天命认证。"
    },
    {
      "name_han": "青城山志",
      "logic_thesis": "青城为天师道发祥、‘青城天下幽’：幽静藏真、正一盟威可役鬼神，山志论证地理之幽与法箓之正共同构成安宅镇邪、正命延生的操作场。",
      "logic_chain": "1) 张陵鹤鸣、青城传道，建立正一契约式秩序。2) 幽深山谷利于入静、藏气、避世炼形。3) 宫观沿革证明法统不断则山灵不散。4) 符箓斋醮把私人命运纳入天师契约。5) 故逻辑：幽地聚气→正法立约→命盘可藉仪式重订边界。",
      "logic_practice": "1) 看正官、七杀、印星是否构成‘法统/约束’可用。2) 宅运、流年神煞扰宅时，取青城式‘幽静方位’安香火。3) 喜神为木土者宜山居、入静、学法类大运。4) 鬼劫重者先立约（戒律、合同、戒色财）再开运。5) 择甲乙寅卯与己土日做安宅、传度、起课。",
      "logic_compare": "与阁皂、茅山同属符箓法系，但青城更重天师盟威与蜀地幽静。较武当帝敕宫观气派，青城志更强调‘幽’与早期正一民间道团结构，命理上偏契约约束与镇宅。"
    },
    {
      "name_han": "阁皂山志",
      "logic_thesis": "阁皂为灵宝祖庭、三山符箓之一：经箓传授即身份与气场升级，山志逻辑是‘得箓则职、职定则命位可迁’，强调灵宝中和度人。",
      "logic_chain": "1) 葛玄炼丹、灵宝经法托此山。2) 与龙虎、茅山并列授箓，形成制度化法位阶梯。3) 志载宫观兴衰与宗师谱系，证明法统即气运载体。4) 灵宝重斋醮度人，个人修真与公共救度一体。5) 故：得箓=获得宇宙行政身份→能合法调动相应气机。",
      "logic_practice": "1) 查官杀印是否成格：有‘职’象则适合授职、考证、拜师节点。2) 食伤生财有力者，可应灵宝‘度人’利众事业。3) 大运见印官连续，宜进修、受戒、拿证、改职称。4) 空亡官印之年忌假名伪职，先补实学。5) 流年用神合官印日做注册、开坛、签约。",
      "logic_compare": "较茅山上清之存思上清，阁皂偏灵宝斋醮与度人经典。与龙虎正一并列三山时，阁皂叙事更中和普度；命理对应‘职箓身份’与公共法会气场，而非仅个人飞升。"
    },
    {
      "name_han": "终南山志",
      "logic_thesis": "终南靠近帝京而又隔世，志书以‘仕隐双修、终南捷径’张力为核：山可藏道亦可猎名，真逻辑是心远地偏则气清，心近名利则山亦成捷径幻象。",
      "logic_chain": "1) 终南为长安屏障，隐士与朝士空间重叠。2) 洞天记载证明其确可修道。3) ‘终南捷径’典故警示：地理清幽不保证心清。4) 真隐则得山气，伪隐则耗名德。5) 故论证：地理条件必要，心性定向才决定命气走向。",
      "logic_practice": "1) 看官杀与印比：官旺想退隐须防‘假隐真求名’。2) 食伤泄秀、印星清纯者，宜真隐进修大运。3) 财官双显之年慎挂名出山，易成捷径反噬。4) 驿马会禄马可择近京之山居‘半隐’过渡。5) 子丑亥月静修、巳午未月慎高调。",
      "logic_compare": "较青城之远蜀幽深，终南更贴权力中心，故志中常含仕隐张力。较华山绝险超凡，终南可进可退；命理应用特别警惕名利伪装的修道运，强调心性定向。"
    },
    {
      "name_han": "茅山全志",
      "logic_thesis": "茅山为第八洞天、第一福地，上清宗坛：三茅真君与魏杨陶经法证明‘存思上清、诵经炼神’可升迁命阶，山志以宗谱、宫观、洞府构建完整修真地理操作系统。",
      "logic_chain": "1) 三茅得道命名，山即祖气。2) 上清经系重存神、飞步、读经，由内景改命。3) 元明志书系统化洞宫、谱系、灵验，使法统可核验。4) 福地逻辑：居福地受福荫，但须行上清之清。5) 故：洞天福地+上清心法=稳定、可传承的改命气场。",
      "logic_practice": "1) 日主喜清气（印比纯、食伤秀）者最契上清存思路线。2) 查长生、冠带、临官位是否落东南/东南方位类福地。3) 大运印星清透宜读经、闭关、拜祖庭。4) 浊财七杀混杂年，先清心戒行再入山。5) 用神为木火者择卯巳时做存思、诵经、祈福。",
      "logic_compare": "较阁皂灵宝之度人外斋，茅山全志更重上清内存与宗师谱系完整性。较青城正一盟威，茅山偏上清仙道阶位；在命理上更强调‘清’‘福地’与经法阶梯式升迁，而非单次符命镇压。"
    }
  ]
}
